import { sha256 } from "@noble/hashes/sha256";
import { bytesToHex, concatBytes, hexToBytes, utf8ToBytes } from "@noble/hashes/utils";

/**
 * Verifiable randomness plumbing.
 *
 * Design: each round gets a 32-byte seed. Before any turn is played the server
 * publishes `commit = sha256(seed)` ("seed commitment"). After the round it
 * reveals the seed. Every deal is derived from the seed with a documented,
 * platform-independent keystream, so anyone can recompute the exact card order
 * and compare it to the on-chain record.
 *
 * In devnet "trusted oracle" mode the seed is generated by the settlement
 * oracle and recorded on-chain. In production the seed is the output of a
 * Switchboard On-Demand randomness account (see docs/vrf.md); everything
 * downstream — commitment, derivation, verification — is identical.
 */

export const SEED_BYTES = 32;

function toBytes(seed: Uint8Array | string): Uint8Array {
  if (typeof seed === "string") {
    return hexToBytes(seed.startsWith("0x") ? seed.slice(2) : seed);
  }
  return seed;
}

export function seedToHex(seed: Uint8Array | string): string {
  return typeof seed === "string" ? seed.toLowerCase() : bytesToHex(seed);
}

export function generateSeed(): Uint8Array {
  const out = new Uint8Array(SEED_BYTES);
  globalThis.crypto.getRandomValues(out);
  return out;
}

/** sha256(seed) as lowercase hex. Published before play. */
export function commitSeed(seed: Uint8Array | string): string {
  return bytesToHex(sha256(toBytes(seed)));
}

export function verifyCommitment(seed: Uint8Array | string, commitment: string): boolean {
  const expected = commitSeed(seed);
  const actual = commitment.toLowerCase().replace(/^0x/, "");
  if (expected.length !== actual.length) return false;
  // Constant-time-ish compare; commitments are public so this is belt & braces.
  let diff = 0;
  for (let i = 0; i < expected.length; i += 1) {
    diff |= expected.charCodeAt(i) ^ actual.charCodeAt(i);
  }
  return diff === 0;
}

/**
 * Deterministic SHA-256 counter-mode byte stream.
 * Block i = sha256(seed || 0x00 || u32be(i)). Values are unbiased via rejection
 * sampling, so no modulo bias is introduced into card shuffles.
 */
export class RandomStream {
  private readonly seed: Uint8Array;
  private counter = 0;
  private block: Uint8Array = new Uint8Array(32);
  private offset = 32;

  constructor(seed: Uint8Array | string) {
    const bytes = toBytes(seed);
    if (bytes.length !== SEED_BYTES) {
      throw new Error(`Seed must be ${SEED_BYTES} bytes, got ${bytes.length}`);
    }
    this.seed = bytes;
  }

  private nextBlock(): void {
    const counterBytes = new Uint8Array(4);
    new DataView(counterBytes.buffer).setUint32(0, this.counter, false);
    this.block = sha256(concatBytes(this.seed, new Uint8Array([0]), counterBytes));
    this.counter += 1;
    this.offset = 0;
  }

  u32(): number {
    if (this.offset + 4 > this.block.length) this.nextBlock();
    const view = new DataView(this.block.buffer, this.block.byteOffset + this.offset, 4);
    this.offset += 4;
    return view.getUint32(0, false);
  }

  /** Unbiased integer in [0, maxExclusive). */
  int(maxExclusive: number): number {
    if (!Number.isInteger(maxExclusive) || maxExclusive < 1 || maxExclusive > 0x1_0000_0000) {
      throw new Error("maxExclusive out of range");
    }
    const limit = Math.floor(0x1_0000_0000 / maxExclusive) * maxExclusive;
    // eslint-disable-next-line no-constant-condition
    while (true) {
      const value = this.u32();
      if (value < limit) return value % maxExclusive;
    }
  }

  bytes(n: number): Uint8Array {
    const out = new Uint8Array(n);
    for (let i = 0; i < n; i += 1) out[i] = this.int(256);
    return out;
  }

  /** In-place unbiased Fisher-Yates using this stream. */
  shuffle<T>(items: T[]): T[] {
    for (let i = items.length - 1; i > 0; i -= 1) {
      const j = this.int(i + 1);
      const a = items[i] as T;
      const b = items[j] as T;
      items[i] = b;
      items[j] = a;
    }
    return items;
  }
}

/**
 * Domain-separated sub-stream. Turn/deal randomness must not depend on how many
 * values earlier turns consumed, otherwise a timeout or a skipped player would
 * shift every later outcome (and make on-chain verification order-dependent).
 */
export function deriveStream(seed: Uint8Array | string, ...domain: Array<string | number>): RandomStream {
  const seedBytes = toBytes(seed);
  const tag = utf8ToBytes(`wagerwake:v1:${domain.join(":")}`);
  const sub = sha256(concatBytes(seedBytes, new Uint8Array([0]), tag));
  return new RandomStream(sub);
}

export function deriveBytes(seed: Uint8Array | string, ...domain: Array<string | number>): Uint8Array {
  const seedBytes = toBytes(seed);
  const tag = utf8ToBytes(`wagerwake:v1:${domain.join(":")}`);
  return sha256(concatBytes(seedBytes, new Uint8Array([0]), tag));
}
